const express = require('express');
const { MongoClient, ObjectId } = require('mongodb');
const crypto = require('crypto');
const app = express();

app.use(express.json());

const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017';
let db;

MongoClient.connect(MONGO_URI).then(client => {
  db = client.db('orchestrator');
});

// Middleware: extract tenant from verified JWT (simplified)
function tenantAuth(req, res, next) {
  const tenantId = req.headers['x-tenant-id'];
  const apiKey = req.headers['x-api-key'];
  if (!tenantId || !apiKey) return res.status(401).json({ error: 'Unauthorized' });
  req.tenantId = tenantId;
  req.apiKey = apiKey;
  next();
}

// Derive a non-reversible identifier for the caller's API key so we never
// persist the raw secret in the database (CWE-312).
function apiKeyFingerprint(apiKey) {
  return crypto.createHash('sha256').update(String(apiKey)).digest('hex');
}

// Container spec normalization layer
class ContainerSpec {
  constructor(raw) {
    this.image = String(raw.image || '');
    this.cpu = Number(raw.cpu) || 1;
    this.memory = Number(raw.memory) || 512;
    this.env = this._sanitizeEnv(raw.env);
    this.labels = this._normalizeLabels(raw.labels);
  }

  _sanitizeEnv(env) {
    if (!env || typeof env !== 'object') return {};
    const clean = {};
    for (const [k, v] of Object.entries(env)) {
      clean[String(k)] = String(v);
    }
    return clean;
  }

  _normalizeLabels(labels) {
    if (!labels || typeof labels !== 'object') return {};
    const normalized = {};
    for (const [k, v] of Object.entries(labels)) {
      normalized[String(k).toLowerCase().replace(/[^a-z0-9._-]/g, '')] = String(v);
    }
    return normalized;
  }
}

// Query builder for multi-tenant container lookups
class TenantQueryBuilder {
  constructor(tenantId) {
    this.tenantId = tenantId;
    this.filters = { tenantId: this.tenantId };
  }

  withStatus(status) {
    if (status) this.filters.status = String(status);
    return this;
  }

  withLabels(labelSelector) {
    if (labelSelector && typeof labelSelector === 'object') {
      for (const [key, value] of Object.entries(labelSelector)) {
        const sanitizedKey = String(key).replace(/[$]/g, '');
        this.filters[`labels.${sanitizedKey}`] = String(value);
      }
    }
    return this;
  }

  withNamePattern(pattern) {
    if (pattern) {
      this.filters.name = { $regex: this._escapeRegex(String(pattern)), $options: 'i' };
    }
    return this;
  }

  _escapeRegex(str) {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  build() {
    return this.filters;
  }
}

// Deploy a new container
app.post('/api/v1/containers', tenantAuth, async (req, res) => {
  try {
    const spec = new ContainerSpec(req.body.spec);
    const container = {
      tenantId: req.tenantId,
      name: String(req.body.name || `container-${crypto.randomUUID()}`),
      spec: spec,
      status: 'pending',
      createdAt: new Date(),
      metadata: { deployedBy: apiKeyFingerprint(req.apiKey) }
    };
    const result = await db.collection('containers').insertOne(container);
    res.status(201).json({ id: result.insertedId, container });
  } catch (err) {
    res.status(500).json({ error: 'Deployment failed' });
  }
});

// List containers with filtering
app.get('/api/v1/containers', tenantAuth, async (req, res) => {
  try {
    const builder = new TenantQueryBuilder(req.tenantId);
    builder.withStatus(req.query.status);
    builder.withNamePattern(req.query.name);
    if (req.query.labels) {
      try {
        const labelSelector = JSON.parse(req.query.labels);
        builder.withLabels(labelSelector);
      } catch (e) { /* ignore malformed labels */ }
    }
    const query = builder.build();
    const containers = await db.collection('containers').find(query).limit(100).toArray();
    res.json({ containers, count: containers.length });
  } catch (err) {
    res.status(500).json({ error: 'Query failed' });
  }
});

// Scale container replicas
app.patch('/api/v1/containers/:id/scale', tenantAuth, async (req, res) => {
  try {
    const containerId = req.params.id;
    if (!ObjectId.isValid(containerId)) return res.status(400).json({ error: 'Invalid ID' });
    const replicas = Math.min(Math.max(Number(req.body.replicas) || 1, 1), 50);
    const result = await db.collection('containers').updateOne(
      { _id: new ObjectId(containerId), tenantId: req.tenantId },
      { $set: { 'spec.replicas': replicas, updatedAt: new Date() } }
    );
    if (result.matchedCount === 0) return res.status(404).json({ error: 'Not found' });
    res.json({ scaled: true, replicas });
  } catch (err) {
    res.status(500).json({ error: 'Scale failed' });
  }
});

// Bulk operations endpoint
app.post('/api/v1/containers/bulk', tenantAuth, async (req, res) => {
  try {
    const { action, selector } = req.body;
    if (!['stop', 'start', 'restart'].includes(action)) {
      return res.status(400).json({ error: 'Invalid action' });
    }
    const query = { tenantId: req.tenantId };
    if (selector && selector.status) {
      query.status = String(selector.status);
    }
    if (selector && selector.labelMatch) {
      if (typeof selector.labelMatch === 'object' && !Array.isArray(selector.labelMatch)) {
        for (const [k, v] of Object.entries(selector.labelMatch)) {
          const safeKey = String(k).replace(/[$]/g, '');
          query[`labels.${safeKey}`] = String(v);
        }
      }
    }
    const result = await db.collection('containers').updateMany(
      query,
      { $set: { status: action === 'stop' ? 'stopped' : 'running', updatedAt: new Date() } }
    );
    res.json({ affected: result.modifiedCount });
  } catch (err) {
    res.status(500).json({ error: 'Bulk operation failed' });
  }
});

app.listen(3000, () => console.log('Orchestrator running on :3000'));
